              <div className="mos-cell" data-mos="" style={{borderRadius: '16px', aspectRatio: '1/1', transitionDelay: '.08s'}}><img src="/landing-mobile/dc7ee0fa.webp" alt="Phone showing creator dashboard with new opportunities, active deal, and payment received" style={{objectPosition: 'center 45%'}} width={900} height={720} decoding="async" loading="lazy" /></div>
